"""The rule card in English: the card the Chinese tests pin, generated by the same code from the same
scenario fields (``task_en`` and each claim's ``say_en`` beside ``task`` and ``say``), saying what the
Chinese says - the same results, numbers, conditions, units, evidence rules, budget and overrun rule."""
from __future__ import annotations

import copy
import os
import re
import subprocess
import sys
from collections import Counter
from dataclasses import replace
from pathlib import Path

import pytest

from stmbench.trackB import rules as R
from stmsim.scenario import HIDDEN_SCHEMA, Scenario

ROOT = Path(__file__).resolve().parent.parent
SCEN = ROOT / "stmbench" / "trackB" / "scenarios"
PAPERS = sorted(SCEN.glob("P*.yaml"))
NAMES = [p.name for p in PAPERS]
P4 = SCEN / "P4_atom_positioning_cu111.yaml"

#: Han, kana and hangul, CJK punctuation and symbols, and the full-width forms (，：（）；、 ...)
_CJK = re.compile("[⺀-⿟　-㏿㐀-䶿一-鿿가-힯豈-﫿"
                  "︰-﹏＀-￯]")

#: What counts as a number: an Arabic-numeral literal with its sign and decimal part, wherever it
#: stands - "6°", "0.5 nm", "-0.45 V", "v1", "E0", a year, a list marker. Both languages write every
#: parameter of a rule that way, so this takes in what the card reads from the scenario file
#: (tolerances, thresholds, counts, the budget). Chinese numerals (一, 两, 半) and English number
#: words (one, two, half) are not counted: they state structure that no field feeds ("at least one
#: frame", "the two arms"), which the wording tests below pin instead. Values are compared as
#: numbers, so "4.0" and "4" are the same.
_NUMBER = re.compile(r"[-+]?\d+(?:\.\d+)?")

#: names the card carries verbatim: claim ids and report fields (x_nm, F_min, m_e ...)
_IDENTIFIER = re.compile(r"\b[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9]+)+\b")

#: the result channel, the file-name conventions and the report's fields, which both cards name
_VERBATIM = ("ReportResult", ".sxm", ".dat", "frame:N", "sts:N", "zspec:N", "lockin", "evidence", "frame",
             "value", "x_nm", "y_nm")

_AFTER_HOP = ("the last atom hop (dragging an atom, or imaging at a low junction resistance "
              "that carries an atom along)")


def _numbers(text: str) -> Counter:
    return Counter(f"{float(t):g}" for t in _NUMBER.findall(text))


def _identifiers(text: str) -> Counter:
    return Counter(_IDENTIFIER.findall(text))


def _num(x) -> str:
    return f"{float(x):g}"


def _without_english(sc, *, task: bool = False, say: tuple[str, ...] = ()):
    """``sc`` as a file that lacks its English: the task and/or the ``say_en`` of these claims."""
    claims = [{k: v for k, v in c.items() if not (k == "say_en" and c["id"] in say)} for c in sc.claims]
    return replace(sc, task_en="" if task else sc.task_en, claims=claims)


# ── the English text is complete, and says what the Chinese says ──────────────
@pytest.mark.parametrize("name", NAMES)
def test_every_paper_has_its_english_text(name):
    sc = Scenario.load(SCEN / name)
    assert sc.task_en.strip(), f"{name}: no task_en"
    for c in sc.claims:
        assert str(c.get("say_en") or "").strip(), f"{name}: claim {c['id']} has no say_en"


@pytest.mark.parametrize("name", NAMES)
def test_the_english_text_states_the_same_numbers_as_the_chinese(name):
    sc = Scenario.load(SCEN / name)
    pairs = [("task", sc.task, sc.task_en), ("rule card", R.rule_card(sc), R.rule_card(sc, "en")),
             ("task text", R.task_text(sc), R.task_text(sc, "en"))]
    pairs += [(f"say of {c['id']}", c["say"], c["say_en"]) for c in sc.claims]
    for what, zh, en in pairs:
        assert _numbers(en) == _numbers(zh), (name, what, "only in the Chinese:", _numbers(zh) - _numbers(en),
                                              "only in the English:", _numbers(en) - _numbers(zh))


@pytest.mark.parametrize("name", NAMES)
def test_every_claim_id_and_field_name_is_carried_over_verbatim(name):
    sc = Scenario.load(SCEN / name)
    zh, en = R.task_text(sc), R.task_text(sc, "en")
    last = -1
    for cid in sc.claim_ids:
        assert en.count(cid) == zh.count(cid) > 0, (name, cid)
        assert en.index(cid) > last, f"{name}: {cid} is out of order"
        last = en.index(cid)
    # the English names the report's two position fields where the Chinese says "位置类结果"
    both_fields = Counter({"x_nm": 1, "y_nm": 1})
    assert _identifiers(en) == _identifiers(zh) + both_fields, (name, _identifiers(zh) - _identifiers(en),
                                                                _identifiers(en) - _identifiers(zh))
    for token in _VERBATIM:
        if token in zh:
            assert token in en, (name, token)


@pytest.mark.parametrize("name", NAMES)
def test_the_english_text_is_all_english(name):
    sc = Scenario.load(SCEN / name)
    texts = {"task_en": sc.task_en, "task text": R.task_text(sc, "en"), "rule card": R.rule_card(sc, "en"),
             **{f"say_en of {c['id']}": c["say_en"] for c in sc.claims}}
    for what, text in texts.items():
        hit = _CJK.search(text)
        context = text[max(0, hit.start() - 30):hit.start() + 30] if hit else ""
        assert hit is None, f"{name}: {what} has {hit and hit.group()!r}: ...{context}..."
    assert _CJK.search(R.task_text(sc)), "the default is still the Chinese text"


@pytest.mark.parametrize("name", NAMES)
def test_the_chinese_text_does_not_depend_on_the_english(name):
    """``lang`` defaults to ``zh``; the English fields feed nothing into the Chinese text."""
    sc = Scenario.load(SCEN / name)
    bare = _without_english(sc, task=True, say=tuple(sc.claim_ids))
    assert R.task_text(sc) == R.task_text(sc, "zh") == R.task_text(bare)
    assert R.rule_card(sc) == R.rule_card(sc, "zh") == R.rule_card(bare)
    assert R.task_text(sc, "en") == f"{sc.task_en.strip()}\n\n{R.rule_card(sc, 'en')}"


# ── what the English card says, rule by rule ──────────────────────────────────
@pytest.mark.parametrize("name", NAMES)
def test_the_english_card_states_the_budget_the_overrun_rule_uses(name):
    sc = Scenario.load(SCEN / name)
    card = R.rule_card(sc, "en")
    hours = float(sc.budget["sim_hours"])
    assert f"budget is {_num(hours)} {'hour' if hours == 1 else 'hours'} of instrument time" in card
    assert f"If the instrument time used exceeds the budget by more than " \
           f"{_num(round(100 * (R.OVERRUN_TOLERANCE - 1), 6))}%, this reproduction does not count as " \
           f"successful" in card
    assert "paused while the model thinks" in card
    # the file's wire_cmds is a limit of the controller TCP path, which the benchmark instrument does not
    # enforce: the card does not state it
    assert "command" not in card.lower() and str(int(sc.budget["wire_cmds"])) not in card
    assert card.rstrip().endswith("this reproduction does not count as successful.")


@pytest.mark.parametrize("name", NAMES)
def test_every_claim_is_explained_with_its_tolerance_and_evidence_in_english(name):
    sc = Scenario.load(SCEN / name)
    card = R.rule_card(sc, "en")
    for c in sc.claims:
        block = card.split(f"{c['id']}", 1)[1]
        assert "Judged correct when:" in block and "Evidence:" in block
        tol = c.get("tol") or {}
        for key in ("abs", "report_nm"):
            if key in tol:
                assert _num(tol[key]) in block, (c["id"], key)
        if "rel" in tol:
            assert f"{_num(100 * float(tol['rel']))}%" in block, c["id"]
        ev = c["evidence"]
        for key in ("min_fov_nm", "max_nm_per_px", "min_points", "near_nm", "max_centre_dist_nm"):
            if key in ev:
                assert _num(ev[key]) in block, (c["id"], key)


def test_the_p4_verification_frame_is_on_the_english_card():
    """The rule that was missing from P4's task, in English: a close frame, after the last hop, in the
    frame the report names; and the near-tied sites the judge also accepts."""
    sc = Scenario.load(P4)
    claim = next(c for c in sc.claims if c["id"] == "target_site")
    ev, card = claim["evidence"], R.rule_card(sc, "en")
    assert f"have a pixel size (width ÷ number of columns) of at most {_num(ev['max_nm_per_px'])} nm" in card
    assert f"have a field of view (the smaller of width and height) of at least {_num(ev['min_fov_nm'])} nm" in card
    assert f"have started scanning only after {_AFTER_HOP} — what counts is when the scan started, " \
           f"not when it was saved" in card
    assert "the frame named in the frame field" in card
    assert f"by less than {_num(claim['tol']['site_tie_nm'])} nm" in card
    assert "(no report needed)" in card and "(no citation needed)" in card
    assert "It concerns the atom that target_site was matched to" in card
    # 出生 is the position at the start of the episode, not "initial" (which can mean before the last move);
    # the shift applies to that position first, and the site is the one nearest to the shifted point
    assert "at the start of the episode that atom had no other atom within 3 nm" in card
    assert "it now sits exactly on 'the lattice site nearest to the point obtained by shifting its position " \
           "at the start of the episode by (4, 0) nm'" in card
    assert "within 10 nm of the position the moved atom had when the episode began, or of its target " \
           "position" in card
    # the frame names the reported position's conversion, not the atom
    assert "the reported position, converted to the sample using the frame named in the frame field, must " \
           "be within 0.6 nm of an atom that you have moved" in card
    assert "write the same x_nm in the value field" in card


def test_the_english_card_explains_citations_and_coordinates():
    card = R.rule_card(Scenario.load(PAPERS[0]), "en")
    for needle in ("evidence", "frame", ".sxm", ".dat", "counter-clockwise", "drift", "flip its sign",
                   "ReportResult"):
        assert needle in card
    assert re.search(rf"\[Scoring rules v{R.RULES_VERSION}\]", card)
    # every result that carries a position names its frame (P1's orientations are angles with a place)
    assert "for results that carry a position (x_nm, y_nm) you must also name in the frame field" in card
    assert "the centre coordinates of the scan window" in card


def test_the_english_card_keeps_the_pairwise_rules_and_the_either_arm_rule():
    p1 = R.rule_card(Scenario.load(SCEN / "P1_barth1990_au111.yaml"), "en")
    assert "must differ by at least 30°" in p1 and "do not count as two domains" in p1
    # what counts as the true direction, not one more condition on the reported value
    assert p1.count("the herringbone stripes are zigzag-shaped, so the direction of either of the two arms, "
                    "or the mean direction of the two arms, is accepted as the true direction") == 3
    assert "angles are taken modulo 180°" in p1
    p3 = R.rule_card(Scenario.load(SCEN / "P3_corral_cu111.yaml"), "en")
    assert "It must correspond to a different true level than peak_lo_mev" in p3
    assert "The value must be greater than peak_lo_mev" in p3
    assert "from at least one of the 3 lowest-energy true resonance levels" in p3
    assert p3.count("showing no sudden jump along the sweep") == 2
    p5 = R.rule_card(Scenario.load(SCEN / "P5_sader_jarvis_qplus.yaml"), "en")
    assert p5.count("with no jump and no contact along the sweep") == 3


def test_the_english_card_offers_p2_either_route_to_its_evidence():
    card = R.rule_card(Scenario.load(SCEN / "P2_standing_waves_cu111.yaml"), "en")
    assert card.count("any one of the following alternatives will do — (a) cite at least 8 dI/dV spectra") == 2
    assert card.count("; or (b) cite at least 4 constant-current scan maps") == 2
    assert "recorded with the lock-in (lockin) on" in card
    # the Chinese states what each spectrum and map is like without a modal ("须" only before the frame
    # terms of the maps), and the judge counts the qualifying ones among those cited: no "must" is added
    assert card.count("each spectrum is within 8 nm of the nearest scatterer (step edge or adatom), has at "
                      "least 64 points and a bias range covering -0.5 V to 0.1 V") == 2
    assert card.count("the centre of each map is within 10 nm of the nearest scatterer") == 2
    assert "must be within 8 nm" not in card and "must be within 10 nm" not in card
    assert card.count("and the maps must have been scanned in the tunnelling state") == 2
    assert card.count("shows no sudden jump along the sweep (a jump caused by an unstable tip)") == 2
    assert "(positions are binned on a 0.5 nm grid)" in card and "(binned in 10 mV steps)" in card


def test_the_english_card_of_the_repair_asks_for_frame_and_spectra_after_the_last_hop():
    card = R.rule_card(Scenario.load(SCEN / "P3_corral_repair_cu111.yaml"), "en")
    assert f"(no citation needed) after {_AFTER_HOP}, this episode has scanned and saved at least one " \
           f"new frame covering the corral centre; that frame must have been scanned" in card
    assert card.count(f"and acquired after {_AFTER_HOP}") == 2
    assert "this quantity is at least 0.97" in card


def test_the_english_card_never_states_a_hidden_value():
    """Tolerances are public; the values drawn for a seed are not."""
    for p in PAPERS:
        sc = Scenario.load(p)
        card = R.rule_card(sc, "en")
        for seed in (0, 1):
            for block, body in sc.draw_hidden(seed).items():
                for key, val in body.items():
                    if isinstance(val, float):
                        assert f"{val:.4f}" not in card, (sc.id, block, key, val)


@pytest.mark.parametrize("name", NAMES)
def test_the_english_task_leaks_nothing_the_chinese_one_may_not(name):
    """The leak tests of the Chinese task (test_scenario_faults, test_manipulation_realism), in English."""
    sc = Scenario.load(SCEN / name)
    low = sc.task_en.lower()
    for word in ("true value", "hidden", "apex_sigma", "radius_nm", "lambda", "contamination", "immediate"):
        assert word not in low, f"{name}: task_en contains {word!r}"
    for word in ("tip state", "tip condition", "blunt", "double tip", "unstable", "dirty"):
        assert word not in low, f"{name}: task_en must not hint at the tip's condition ({word})"
    assert "ReportResult" in sc.task_en, "the task names the result channel"


# ── one code path: the English follows the file, not a copy of it ─────────────
def test_both_languages_follow_the_fields_the_judge_reads():
    """Change the numbers in the file and both cards change: the English holds no figure of its own."""
    sc = copy.deepcopy(Scenario.load(P4))
    target = next(c for c in sc.claims if c["id"] == "target_site")
    target["evidence"].update(max_nm_per_px=0.37, min_fov_nm=7.5, after_event=None)
    target["tol"].update(report_nm=0.71, site_tie_nm=0.031)
    sc.initial["adatoms"].update(isolation_nm=4.5, target_dx_nm=-3.0, target_dy_nm=1.25)
    next(c for c in sc.claims if c["id"] == "bystander_max_shift_nm")["max"] = 0.43
    sc.budget.update(sim_hours=2.25, wire_cmds=123456)
    for lang in ("zh", "en"):
        card = R.rule_card(sc, lang)
        for new in ("0.37", "7.5", "0.71", "0.031", "4.5", "(-3, 1.25)", "0.43", "2.25"):
            assert new in card, (lang, new)
        assert "123456" not in card, lang                                # a limit nothing applies
    assert _numbers(R.rule_card(sc, "en")) == _numbers(R.rule_card(sc))
    assert "之后才开始扫描" not in R.rule_card(sc) and "only after" not in R.rule_card(sc, "en"), \
        "no after_event, no clause about it"


@pytest.mark.parametrize("name", NAMES)
def test_the_english_fields_touch_no_hidden_draw(name):
    sc = Scenario.load(SCEN / name)
    bare = _without_english(sc, task=True, say=tuple(sc.claim_ids))
    for seed in range(3):
        assert sc.draw_hidden(seed) == bare.draw_hidden(seed)
    assert not {"task_en", "say_en"} & set(HIDDEN_SCHEMA)


# ── what is missing, and which language ───────────────────────────────────────
@pytest.mark.parametrize("name", NAMES)
def test_a_missing_task_en_or_say_en_raises_and_says_which(name):
    sc = Scenario.load(SCEN / name)
    no_task = _without_english(sc, task=True)
    with pytest.raises(ValueError, match=rf"{sc.id}.*task_en"):
        R.task_text(no_task, "en")
    R.rule_card(no_task, "en")                       # the card alone does not need the task
    first = sc.claim_ids[0]
    some = _without_english(sc, say=(first,))
    for call in (R.rule_card, R.task_text):
        with pytest.raises(ValueError, match=rf"say_en of claim {first}"):
            call(some, "en")
    bare = _without_english(sc, task=True, say=tuple(sc.claim_ids))
    with pytest.raises(ValueError) as err:
        R.task_text(bare, "en")
    assert "task_en" in str(err.value) and all(f"say_en of claim {cid}" in str(err.value) for cid in sc.claim_ids)
    assert R.task_text(bare) == R.task_text(sc), "the Chinese text needs none of it"


def test_a_scenario_without_a_card_has_english_only_if_it_has_task_en():
    regression = Scenario.load(SCEN / "B5_repair_blunt.yaml")
    assert R.task_text(regression) == regression.task.strip()
    with pytest.raises(ValueError, match="task_en"):
        R.task_text(regression, "en")
    assert R.task_text(replace(regression, task_en="  Repair the tip.  "), "en") == "Repair the tip."


@pytest.mark.parametrize("lang", ["fr", "", "EN", "zh-CN", None, 1])
def test_an_unknown_language_raises(lang):
    sc = Scenario.load(PAPERS[0])
    for call in (R.rule_card, R.task_text):
        with pytest.raises(ValueError, match="unknown language"):
            call(sc, lang)
    with pytest.raises(ValueError, match="unknown language"):
        R.task_text(Scenario.load(SCEN / "B5_repair_blunt.yaml"), lang)


# ── where the text is handed out ──────────────────────────────────────────────
@pytest.mark.parametrize("name", NAMES)
def test_the_instrument_hands_out_the_english_text_on_request(name):
    from stmbench.instrument import Instrument

    inst = Instrument(Scenario.load(SCEN / name), 0)
    assert inst.task("en") == R.task_text(inst.scenario, "en")
    assert inst.task() == inst.task("zh") == R.task_text(inst.scenario)
    assert inst.task("en") != inst.task()
    with pytest.raises(ValueError, match="unknown language"):
        inst.task("fr")


def test_the_task_subcommand_prints_what_the_agent_is_told(capsys):
    from stmbench import cli

    sc = Scenario.load(P4)
    for argv, want in ((["--lang", "en"], R.task_text(sc, "en")), (["--lang", "zh"], R.task_text(sc)),
                       ([], R.task_text(sc))):
        assert cli.main(["task", "--scenario", sc.id, *argv]) == 0
        assert capsys.readouterr().out == want + "\n"
    assert cli.main(["task", "--scenario", "P4", "--lang", "en"]) == 0          # a prefix that names one
    assert capsys.readouterr().out == R.task_text(sc, "en") + "\n"
    regression = Scenario.load(SCEN / "B5_repair_blunt.yaml")
    assert cli.main(["task", "--scenario", str(SCEN / "B5_repair_blunt.yaml")]) == 0      # a path
    assert capsys.readouterr().out == regression.task.strip() + "\n"


def test_the_task_subcommand_names_what_is_missing_or_ambiguous():
    from stmbench import cli

    with pytest.raises(SystemExit, match="task_en"):
        cli.main(["task", "--scenario", "B5_repair_blunt", "--lang", "en"])
    with pytest.raises(SystemExit, match="P3_corral_cu111.*P3_corral_repair_cu111"):
        cli.main(["task", "--scenario", "P3"])
    with pytest.raises(SystemExit, match="no scenario matches"):
        cli.main(["task", "--scenario", "nothing_like_it"])
    with pytest.raises(SystemExit):
        cli.main(["task", "--scenario", "P4", "--lang", "fr"])           # argparse refuses the choice


def test_the_task_subcommand_writes_utf8_with_plain_line_breaks_into_a_pipe():
    """Redirected into a task file, the text must not depend on the console's code page (an ASCII or
    cp1252 stdout cannot write 'Δ', '÷' or '√') nor turn its line breaks into CR LF (Windows)."""
    env = {**os.environ, "PYTHONIOENCODING": "ascii"}
    for name, lang in (("P4_atom_positioning_cu111", "en"), ("P4_atom_positioning_cu111", "zh"),
                       ("P5_sader_jarvis_qplus", "en"), ("P1_barth1990_au111", "en")):
        done = subprocess.run([sys.executable, "-m", "stmbench.cli", "task", "--scenario", name, "--lang", lang],
                              cwd=ROOT, capture_output=True, env=env)
        assert done.returncode == 0, done.stderr.decode("utf-8", "replace")
        assert done.stdout == (R.task_text(Scenario.load(SCEN / f"{name}.yaml"), lang) + "\n").encode("utf-8")
